from z3 import *

def main():
    names = ["Peter", "Eric", "Alice", "Arnold"]
    smoothies = ["watermelon", "desert", "cherry", "dragonfruit"]
    colors = ["green", "white", "red", "yellow"]

    s = Solver()

    name_pos = {n: Int(n) for n in names}
    smoothie_pos = {v: Int(v) for v in smoothies}
    color_pos = {c: Int(c) for c in colors}

    for var in list(name_pos.values()) + list(smoothie_pos.values()) + list(color_pos.values()):
        s.add(var >= 0, var <= 3)

    s.add(Distinct(*name_pos.values()))
    s.add(Distinct(*smoothie_pos.values()))
    s.add(Distinct(*color_pos.values()))

    s.add(smoothie_pos["dragonfruit"] == name_pos["Eric"])
    s.add(smoothie_pos["cherry"] == 1)
    s.add(smoothie_pos["dragonfruit"] == 3)
    s.add(name_pos["Arnold"] == smoothie_pos["watermelon"])
    s.add(color_pos["white"] == 0)
    s.add(name_pos["Peter"] == color_pos["white"])
    s.add(color_pos["yellow"] == smoothie_pos["watermelon"])
    s.add(color_pos["red"] == smoothie_pos["dragonfruit"])

    if s.check() != sat:
        raise SystemExit

