from z3 import *

def main():
    solver = Solver()

    names = ["Eric", "Arnold", "Alice", "Peter"]
    styles = ["craftsman", "ranch", "victorian", "colonial"]
    drinks = ["water", "tea", "milk", "coffee"]

    name_pos = {name: Int(name) for name in names}
    style_pos = {style: Int(style) for style in styles}
    drink_pos = {drink: Int(drink) for drink in drinks}

    all_vars = list(name_pos.values()) + list(style_pos.values()) + list(drink_pos.values())

    for var in all_vars:
        solver.add(var >= 0, var <= 3)

    solver.add(Distinct(list(name_pos.values())))
    solver.add(Distinct(list(style_pos.values())))
    solver.add(Distinct(list(drink_pos.values())))

    solver.add(name_pos["Eric"] == 2)
    solver.add(drink_pos["water"] == name_pos["Eric"])
    solver.add(drink_pos["milk"] == style_pos["victorian"])
    solver.add(style_pos["ranch"] < style_pos["craftsman"])
    solver.add(name_pos["Arnold"] > name_pos["Alice"])
    solver.add(name_pos["Arnold"] == style_pos["ranch"])
    solver.add(Abs(name_pos["Eric"] - style_pos["victorian"]) == 1)
    solver.add(drink_pos["tea"] != 0)

    if solver.check() != sat:
        print("No solution")
        return

    model = solver.model()

    def get_position(var):
        return model.eval(var, model_completion=True).as_long()

    name_at = {get_position(name_pos[name]): name for name in names}
    style_at = {get_position(style_pos[style]): style for style in styles}
    drink_at = {get_position(drink_pos[drink]): drink for drink in drinks}

    for house_number in range(1, 5):
        pos = house_number - 1
        print(f"House {house_number}: {name_at[pos]}, {style_at[pos]}, {drink_at[pos]}")

if __name__ == "__main__":
    main()

