pos_mother = {v: Int(vn("mother", v)) for v in mothers}
pos_music = {v: Int(vn("music", v)) for v in music}
pos_lunch = {v: Int(vn("lunch", v)) for v in lunch}

s = Solver()

for var in list(pos_name.values()) + list(pos_mother.values()) + list(pos_music.values()) + list(pos_lunch.values()):
    s.add(0 <= var, var <= 4)

s.add(AllDiff(list(pos_name.values())))
s.add(AllDiff(list(pos_mother.values())))
s.add(AllDiff(list(pos_music.values())))
s.add(AllDiff(list(pos_lunch.values())))

s.add(pos_name["Eric"] < pos_music["classical"])
s.add(pos_lunch["grilled cheese"] + 1 == pos_mother["Janelle"])
s.add(pos_mother["Penny"] + 1 == pos_name["Alice"])
s.add(pos_lunch["stir fry"] == pos_name["Peter"])
s.add(pos_name["Alice"] == pos_lunch["spaghetti"])
s.add(pos_name["Eric"] < pos_music["rock"])
s.add(pos_mother["Kailyn"] + 1 == pos_mother["Aniya"])
s.add(pos_music["rock"] != 2)
s.add(pos_lunch["grilled cheese"] + 1 == pos_lunch["stew"])
s.add(pos_music["pop"] == pos_mother["Kailyn"])
s.add(pos_lunch["spaghetti"] == pos_music["jazz"])
s.add(pos_music["pop"] == pos_name["Arnold"])

if s.check() == sat:
    m = s.model()

    def hp(var):
        return m.eval(var, model_completion=True).as_long()

    name_at = [None] * 5
    mother_at = [None] * 5
    music_at = [None] * 5
    lunch_at = [None] * 5

