from z3 import *

houses = [1, 2]
names = ["Eric", "Arnold"]
drinks = ["water", "tea"]
occupations = ["engineer", "doctor"]

name = {}
drink = {}
occupation = {}

for h in houses:
    for v in names:
        name[(h, v)] = Bool(f"name_{h}_{v}")
    for v in drinks:
        drink[(h, v)] = Bool(f"drink_{h}_{v}")
    for v in occupations:
        occupation[(h, v)] = Bool(f"occupation_{h}_{v}")

solver = Solver()

def add_category_constraints(var, values):
    for h in houses:
        solver.add(ExactlyOne([var[(h, v)] for v in values]))
    for v in values:
        solver.add(ExactlyOne([var[(h, v)] for h in houses]))

add_category_constraints(name, names)
add_category_constraints(drink, drinks)
add_category_constraints(occupation, occupations)

for h in houses:
    solver.add(Implies(name[(h, "Eric")], occupation[(h, "doctor")]))

solver.add(
    Or([
        And(drink[(h, "water")], occupation[(h + 1, "doctor")])
        for h in houses[:-1]
    ])
)

if solver.check() == sat:
    model = solver.model()

    def get_value(var, h, values):
        for v in values:
            if is_true(model.evaluate(var[(h, v)], model_completion=True)):
                return v
        return "unknown"

    for h in houses:
        n = get_value(name, h, names)
        d = get_value(drink, h, drinks)
        o = get_value(occupation, h, occupations)
        print(f"House {h}: {n}, {d}, {o}")

