from z3 import *

houses = [1, 2]

categories = [
    ("name", ["Eric", "Arnold"]),
    ("phone", ["iphone 13", "samsung galaxy s21"]),
    ("drink", ["water", "tea"]),
    ("sport", ["basketball", "soccer"]),
]


def var_name(cat, h, attr):
    return f"{cat}_{h}_{attr.replace(' ', '_').replace('-', '_')}"


variables = {}
for cat, attrs in categories:
    for h in houses:
        for attr in attrs:
            variables[(cat, h, attr)] = Bool(var_name(cat, h, attr))

solver = Solver()

for h in houses:
    for cat, attrs in categories:
        solver.add(ExactlyOne([variables[(cat, h, attr)] for attr in attrs]))

for cat, attrs in categories:
    for attr in attrs:
        solver.add(ExactlyOne([variables[(cat, h, attr)] for h in houses]))

solver.add(variables[("name", 2, "Arnold")])
solver.add(Not(variables[("phone", 1, "samsung galaxy s21")]))

for h in houses:
    solver.add(Iff(variables[("name", h, "Eric")], variables[("sport", h, "soccer")]))
    solver.add(Iff(variables[("phone", h, "samsung galaxy s21")], variables[("drink", h, "tea")]))

result = solver.check()

if result == sat:
    model = solver.model()
    cat_attrs = {cat: attrs for cat, attrs in categories}

