        )

from z3 import *

H = 6
names = ["Carol", "Peter", "Arnold", "Alice", "Bob", "Eric"]
occupations = ["lawyer", "teacher", "artist", "engineer", "nurse", "doctor"]
pets = ["dog", "hamster", "rabbit", "cat", "fish", "bird"]

name_idx = {v: i for i, v in enumerate(names)}
occ_idx = {v: i for i, v in enumerate(occupations)}
pet_idx = {v: i for i, v in enumerate(pets)}

name = [Int(f"name_{i + 1}") for i in range(H)]
occ = [Int(f"occupation_{i + 1}") for i in range(H)]
pet = [Int(f"pet_{i + 1}") for i in range(H)]

s = Solver()

for i in range(H):
    s.add(name[i] >= 0, name[i] < len(names))
    s.add(occ[i] >= 0, occ[i] < len(occupations))
    s.add(pet[i] >= 0, pet[i] < len(pets))

s.add(Distinct(*name))
s.add(Distinct(*occ))
s.add(Distinct(*pet))

s.add(name[2] == name_idx["Carol"])
s.add(pet[2] == pet_idx["rabbit"])
s.add(name[4] == name_idx["Arnold"])
s.add(pet[3] != pet_idx["hamster"])
s.add(pet[3] != pet_idx["fish"])

for i in range(H):
    s.add(Implies(name[i] == name_idx["Peter"], pet[i] == pet_idx["dog"]))
    s.add(Implies(pet[i] == pet_idx["dog"], name[i] == name_idx["Peter"]))

for i in range(H):
    s.add(Implies(name[i] == name_idx["Eric"], occ[i] == occ_idx["nurse"]))
    s.add(Implies(occ[i] == occ_idx["nurse"], name[i] == name_idx["Eric"]))

s.add(occ[1] == occ_idx["teacher"])

s.add(Or([
    And(name[i] == name_idx["Alice"], pet[j] == pet_idx["cat"])
    for i in range(H)
    for j in range(i + 1, H)
]))

s.add(Or([
    And(pet[i] == pet_idx["hamster"], name[j] == name_idx["Eric"])
    for i in range(H)
    for j in range(i + 1, H)
]))

s.add(pet[1] != pet_idx["fish"])

s.add(Or([
    And(pet[i] == pet_idx["dog"], occ[i + 1] == occ_idx["artist"])
    for i in range(H - 1)
]))

for i in range(H):
    adjacent_teacher = []
    if i > 0:
        adjacent_teacher.append(occ[i - 1] == occ_idx["teacher"])
    if i < H - 1:
        adjacent_teacher.append(occ[i + 1] == occ_idx["teacher"])
    s.add(Implies(occ[i] == occ_idx["doctor"], Or(adjacent_teacher)))

for i in range(H):
    s.add(Implies(name[i] == name_idx["Bob"], pet[i] == pet_idx["fish"]))
    s.add(Implies(pet[i] == pet_idx["fish"], name[i] == name_idx["Bob"]))

for i in range(H):
    s.add(Implies(occ[i] == occ_idx["lawyer"], pet[i] == pet_idx["hamster"]))
    s.add(Implies(pet[i] == pet_idx["hamster"], occ[i] == occ_idx["lawyer"]))

if s.check() == sat:
    m = s.model()
    for i in range(H):
        n = m.eval(name[i], model_completion=True).as_long()
        o = m.eval(occ[i], model_completion=True).as_long()
        p = m.eval(pet[i], model_completion=True).as_long()
        print(f"House {i + 1}: {names[n]}, {occupations[o]}, {pets[p]}")

from z3 import *

H = 6

categories = {
    "name": ["Bob", "Carol", "Eric", "Alice", "Peter", "Arnold"],
    "vacation": ["camping", "cruise", "mountain", "cultural", "city", "beach"],
    "pet": ["fish", "hamster", "bird", "rabbit", "dog", "cat"],
    "nationality": ["brit", "swede", "german", "norwegian", "dane", "chinese"],
    "book": ["biography", "romance", "mystery", "fantasy", "science fiction", "historical fiction"],
    "car": ["tesla model 3", "bmw 3 series", "honda civic", "chevrolet silverado", "toyota camry", "ford f150"],
}

x = {}
for cat, vals in categories.items():
    for h in range(H):
        for vi in range(len(vals)):
            x[(cat, h, vi)] = Bool(f"{cat}_{h}_{vi}")

s = Solver()

def exactly_one(lits):
    s.add(Or(lits))
    for i in range(len(lits)):
        for j in range(i + 1, len(lits)):
            s.add(Not(And(lits[i], lits[j])))

for cat, vals in categories.items():
    for h in range(H):
        exactly_one([x[(cat, h, vi)] for vi in range(len(vals))])
    for vi in range(len(vals)):
        exactly_one([x[(cat, h, vi)] for h in range(H)])

idx = {cat: {v: i for i, v in enumerate(vals)} for cat, vals in categories.items()}

def at(cat, h, val):
    return x[(cat, h, idx[cat][val])]

def same_house(c1, v1, c2, v2):
    for h in range(H):
        s.add(at(c1, h, v1) == at(c2, h, v2))

def directly_left(c1, v1, c2, v2):
    s.add(Or([at(c1, h, v1) & at(c2, h + 1, v2) for h in range(H - 1)]))

def one_house_between(c1, v1, c2, v2, ordered=False):
    clauses = []
    for h in range(H - 2):
        clauses.append(at(c1, h, v1) & at(c2, h + 2, v2))
        if not ordered:
            clauses.append(at(c2, h, v1) & at(c1, h + 2, v2))
    s.add(Or(clauses))

def right_of(c_left, v_left, c_right, v_right):
    clauses = []
    for i in range(H):
        for j in range(i + 1, H):
            clauses.append(at(c_left, i, v_left) & at(c_right, j, v_right))
    s.add(Or(clauses))

def left_of(c_left, v_left, c_right, v_right):
    clauses = []
    for i in range(H):
        for j in range(i + 1, H):
            clauses.append(at(c_left, i, v_left) & at(c_right, j, v_right))
    s.add(Or(clauses))

same_house("book", "fantasy", "name", "Peter")
right_of("nationality", "dane", "nationality", "chinese")
same_house("car", "tesla model 3", "pet", "hamster")
same_house("name", "Carol", "vacation", "beach")
s.add(at("pet", 1, "cat"))
one_house_between("book", "mystery", "vacation", "city")
s.add(at("car", 0, "honda civic"))
directly_left("book", "science fiction", "vacation", "city")
same_house("nationality", "brit", "car", "honda civic")
one_house_between("book", "fantasy", "car", "toyota camry")
same_house("pet", "bird", "car", "toyota camry")
s.add(Not(at("nationality", 2, "dane")))
s.add(Not(at("name", 5, "Eric")))
same_house("book", "romance", "vacation", "camping")
same_house("name", "Arnold", "vacation", "cruise")
s.add(at("pet", 4, "dog"))
directly_left("vacation", "camping", "pet", "rabbit")
same_house("car", "ford f150", "pet", "rabbit")
directly_left("book", "fantasy", "name", "Eric")
same_house("nationality", "german", "car", "bmw 3 series")
s.add(Not(at("vacation", 0, "cultural")))
s.add(Not(at("book", 5, "mystery")))
left_of("book", "historical fiction", "vacation", "camping")
same_house("nationality", "dane", "name", "Bob")
one_house_between("nationality", "dane", "nationality", "chinese")
right_of("vacation", "cruise", "nationality", "swede")
s.add(Not(at("name", 2, "Eric")))

if s.check() != sat:
    raise SystemExit

m = s.model()
for h in range(H):
    row = []
    for cat in ["name", "vacation", "pet", "nationality", "book", "car"]:
        for vi, v in enumerate(categories[cat]):
            if m[x[(cat, h, vi)]].is_true():
                row.append(v)
                break
    print(f"House {h + 1}: {', '.join(row)}")

from z3 import *

houses = [1, 2]
names = ["Eric", "Arnold"]
drinks = ["water", "tea"]
cigars = ["prince", "pall mall"]


def var_name(value):
    return value.replace(" ", "_")


name_pos = {n: Int(var_name(n)) for n in names}
drink_pos = {d: Int(var_name(d)) for d in drinks}
cigar_pos = {c: Int(var_name(c)) for c in cigars}

solver = Solver()

