from z3 import *

def main():
    s = Solver()

    name_eric = IntVar("name_eric")
    name_arnold = IntVar("name_arnold")

    nat_dane = IntVar("nat_dane")
    nat_brit = IntVar("nat_brit")

    for var in [name_eric, name_arnold, nat_dane, nat_brit]:
        s.add(var >= 1, var <= 2)

    s.add(Distinct(name_eric, name_arnold))
    s.add(Distinct(nat_dane, nat_brit))

    s.add(nat_brit != 1)
    s.add(name_arnold != 2)

    if s.check() == sat:
        m = s.model()

        names = {
            m[name_eric].as_long(): "Eric",
            m[name_arnold].as_long(): "Arnold"
        }

        nationalities = {
            m[nat_dane].as_long(): "dane",
            m[nat_brit].as_long(): "brit"
        }

        for house in range(1, 3):
            print(f"House {house}: {names[house]}, {nationalities[house]}")

if __name__ == "__main__":
    main()

