def main():
    n_houses = 3

    categories = {
        "name": ["Eric", "Arnold", "Peter"],
        "vacation": ["beach", "mountain", "city"],
        "education": ["high school", "bachelor", "associate"],
        "animal": ["cat", "bird", "horse"],
    }

    solver = Solver()
    variables = {}

    for category, values in categories.items():
        variables[category] = [Int(f"{category}_house_{h + 1}") for h in range(n_houses)]

        for h in range(n_houses):
            solver.add(Or(*[variables[category][h] == j for j in range(len(values))]))

        solver.add(Distinct(*variables[category]))

    def idx(category, value):
        return categories[category].index(value)

    # 1. The person with an associate's degree is Eric.
    for h in range(n_houses):
        solver.add(Implies(
            variables["education"][h] == idx("education", "associate"),
            variables["name"][h] == idx("name", "Eric")
        ))
        solver.add(Implies(
            variables["name"][h] == idx("name", "Eric"),
            variables["education"][h] == idx("education", "associate")
        ))

    # 2. The person who enjoys mountain retreats is in the second house.
    solver.add(variables["vacation"][1] == idx("vacation", "mountain"))

    # 3. Arnold is somewhere to the right of the cat lover.
    solver.add(Or(*[
        And(
            variables["name"][i] == idx("name", "Arnold"),
            variables["animal"][j] == idx("animal", "cat")
        )
        for i in range(n_houses)
        for j in range(n_houses)
        if i > j
    ]))

    # 4. The bird keeper is the person who enjoys mountain retreats.
    for h in range(n_houses):
        solver.add(Implies(
            variables["vacation"][h] == idx("vacation", "mountain"),
            variables["animal"][h] == idx("animal", "bird")
        ))
        solver.add(Implies(
            variables["animal"][h] == idx("animal", "bird"),
            variables["vacation"][h] == idx("vacation", "mountain")
        ))

    # 5. The person with a high school diploma is somewhere to the right of the person who loves beach vacations.
    solver.add(Or(*[
        And(
            variables["education"][i] == idx("education", "high school"),
            variables["vacation"][j] == idx("vacation", "beach")
        )
        for i in range(n_houses)
        for j in range(n_houses)
        if i > j
    ]))

    # 6. The person with a high school diploma is in the third house.
    solver.add(variables["education"][2] == idx("education", "high school"))

    # 7. The person with an associate's degree is not in the first house.
    solver.add(variables["education"][0] != idx("education", "associate"))

    if solver.check() == sat:
        model = solver.model()

        for h in range(n_houses):
            row = []
            for category in ["name", "vacation", "education", "animal"]:
                value_index = int(model.evaluate(variables[category][h], model_completion=True))
                row.append(categories[category][value_index])

            print(f"House {h + 1}: " + ", ".join(row))
    else:
        print("No solution")

