from z3 import *

def main():
    houses = [1, 2, 3, 4]
    names = ["Arnold", "Peter", "Eric", "Alice"]
    lunches = ["pizza", "grilled cheese", "spaghetti", "stew"]

    name_index = {name: i for i, name in enumerate(names)}
    lunch_index = {lunch: i for i, lunch in enumerate(lunches)}

    name_vars = [Int(f"name_{h}") for h in houses]
    lunch_vars = [Int(f"lunch_{h}") for h in houses]

    solver = Solver()

    for var in name_vars:
        solver.add(var >= 0, var < len(names))
    for var in lunch_vars:
        solver.add(var >= 0, var < len(lunches))

    solver.add(Distinct(name_vars))
    solver.add(Distinct(lunch_vars))

    # Alice is not in the second house.
    solver.add(name_vars[1] != name_index["Alice"])

    # Eric is in the fourth house.
    solver.add(name_vars[3] == name_index["Eric"])

    # The person who loves stew is in the second house.
    solver.add(lunch_vars[1] == lunch_index["stew"])

    # The person who loves eating grilled cheese is in the fourth house.
    solver.add(lunch_vars[3] == lunch_index["grilled cheese"])

    # Peter is the person who loves the spaghetti eater, interpreted as Peter eats spaghetti.
    for h in range(4):
        solver.add(
            Implies(
                name_vars[h] == name_index["Peter"],
                lunch_vars[h] == lunch_index["spaghetti"]
            )
        )

    # Arnold is somewhere to the right of the person who eats spaghetti.
    right_of_spaghetti = Or(
        And(
            name_vars[i] == name_index["Arnold"],
            lunch_vars[j] == lunch_index["spaghetti"],
            i > j
        )
        for i in range(4)
        for j in range(4)
    )
    solver.add(right_of_spaghetti)

    if solver.check() == sat:
        model = solver.model()
        for h in houses:
            name_val = model.eval(name_vars[h - 1], model_completion=True).as_long()
            lunch_val = model.eval(lunch_vars[h - 1], model_completion=True).as_long()
            print(f"House {h}: {names[name_val]}, {lunches[lunch_val]}")
    else:
        print("No solution")

if __name__ == "__main__":
    main()

